#include "engine/simulation/simulation.hpp"
namespace origin{void Simulation::initialize(std::uint32_t seed){clock_.reset();environment_.reset();world_.generate_vearth(seed);RigidBody b;b.position={20,22};b.velocity={1.2,0};b.mass_kg=40;b.radius_m=.45;b.restitution=.35;entities_.create("Stone-1",Material::Rock,b);b.position={42,23};b.velocity={-.8,0};entities_.create("Stone-2",Material::Rock,b);events_.publish({0,0,EventType::SimulationStarted,"VEarth initialized"});}void Simulation::step(){double dt=clock_.fixed_dt();environment_.step(world_,clock_.seconds(),dt);chemistry_.update(world_);physics_.step(entities_,world_,dt);clock_.advance();events_.publish({clock_.tick(),clock_.seconds(),EventType::SimulationStepped,"step"});}}
